    concurrentUploadsDescription: 'Do koľkých tlačiarní môže front naraz posielať súbory. Tlačiarne prijímajú súbory pomaly (veľká tlač môže trvať niekoľko minút) a každá čaká, kým na ňu príde rad – pri väčšom počte tlačiarní teda zvýšenie tejto hodnoty zabráni tomu, aby posledná tlačiareň v dávke čakala na všetky prenosy pred ňou. Znížte ju, ak vaša sieť alebo hostiteľ Bambuddy nezvláda paralelné prenosy.',
