    preheatTitle: 'Predohrev a prehriatie',
    preheatDescription: 'Pred spustením každej tlače z frontu zohriať podložku (a komoru, ak je podporovaná) a udržať teplotu. Užitočné pre technické filamenty (PA, ABS) na tlačiarňach bez aktívneho ohrevu komory – podložka počas odpočtu prehriatia ohrieva komoru sálaním. Cieľová teplota podložky sa číta zo súboru tlače; správanie komory závisí od modelu tlačiarne.',
